impl MkdirContext {
    // Parent permission bits are not applied on windows.
    #[allow(unused_variables)]
    fn create_dir(&self, target: &DirectorySpec, perms: &CreationMode) -> UResult<bool> {
        if target.path().exists() && !self.recursive {
            return Err(DirectorySpec::error_exists(target.label()));
        }
        if target.path() == Path::new("") {
            return Ok(false);
        }

        if self.recursive {
            match target.parent_path() {
                Some(parent_path) => {
                    let parent = DirectorySpec::from_path(parent_path.to_path_buf());
                    self.create_dir(&parent, &perms.as_parent())?;
                }
                None => {
                    DirectorySpec::discard_missing_tree();
                }
            }
        }
        match std::fs::create_dir(target.path()) {
            Ok(()) => {
                if self.verbose {
                    println!(
                        "{}: created directory {}",
                        uucore::util_name(),
                        target.path().quote()
                    );
                }
                #[cfg(not(windows))]
                if perms.is_parent() {
                    // directories created by -p have permission bits set to '=rwx,u+wx',
                    // which is umask modified by 'u+wx'
                    chmod(target.path(), (!perms.umask() & 0o0777) | 0o0300)?;
                }
                Ok(true)
            }
            Err(_) if target.path().is_dir() => Ok(false),
            Err(e) => Err(e.into()),
        }
    }
}

